// inviteTTL is how long an invite can be accepted after it was created.
const inviteTTL = 7 * 24 * time.Hour

// ErrInviteUsed and ErrInviteExpired are returned by AcceptInvite for a token whose invite was accepted or has expired.
var (
	ErrInviteUsed    = errors.New("invite already accepted")
	ErrInviteExpired = errors.New("invite expired")
)

// newInviteToken returns 32 random bytes in unpadded base64url.
func newInviteToken() string {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		panic(err) // crypto/rand does not fail on supported platforms
	}
	return base64.RawURLEncoding.EncodeToString(b)
}

// hashInviteToken is what the store keeps of an invite's token.
func hashInviteToken(token string) string {
	sum := sha256.Sum256([]byte(token))
	return hex.EncodeToString(sum[:])
}

// CreateInvite invites an email address to join an organization with a role. It revokes any older pending invite to
// the same address. The returned invite carries the token for the email; the store keeps only its hash.
func (s *Store) CreateInvite(orgID, email string, role Role, invitedBy string, now time.Time) (Invite, error) {
	email = strings.TrimSpace(email)
	if !validEmail(email) {
		return Invite{}, invalid("an invite needs a valid email address")
	}
	if !role.Valid() || role == RoleOwner {
		return Invite{}, invalid("an invite's role is admin, billing, member or viewer")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[orgID]; !ok {
		return Invite{}, ErrNotFound
	}
	if uid, ok := s.usersByEmail[normEmail(email)]; ok {
		if _, member := s.members[memberKey{orgID, uid}]; member {
			return Invite{}, ErrAlreadyMember
		}
	}
	t := now.UTC()
	for id, old := range s.invites {
		if old.OrgID == orgID && normEmail(old.Email) == normEmail(email) && old.AcceptedAt == nil && old.RevokedAt == nil {
			old.RevokedAt = &t
			s.invites[id] = old
		}
	}
	token := newInviteToken()
	inv := Invite{ID: s.newID("inv"), OrgID: orgID, Email: email, Role: role, Token: token, TokenHash: hashInviteToken(token),
		InvitedBy: invitedBy, CreatedAt: t, ExpiresAt: t.Add(inviteTTL)}
	stored := inv
	stored.Token = ""
	s.invites[inv.ID] = stored
	return inv, nil
}

