484	// AcceptInvite accepts the invite with this token: it finds or creates the user for the invited address (named name),
485	// makes them a member with the invite's role and gives them a first API key. An unknown or revoked token is ErrNotFound,
486	// an accepted one ErrInviteUsed and an expired one ErrInviteExpired.
487	func (s *Store) AcceptInvite(token, name string, now time.Time) (User, Member, APIKey, error) {
488		s.mu.Lock()
489		defer s.mu.Unlock()
490		hash := hashInviteToken(token)
491		var inv Invite
492		found := false
493		for _, i := range s.invites {
494			if i.TokenHash == hash {
495				inv, found = i, true
496				break
497			}
498		}
499		if !found || inv.RevokedAt != nil {
500			return User{}, Member{}, APIKey{}, ErrNotFound
501		}
502		if inv.AcceptedAt != nil {
503			return User{}, Member{}, APIKey{}, ErrInviteUsed
504		}
505		if now.After(inv.ExpiresAt) {
506			return User{}, Member{}, APIKey{}, ErrInviteExpired
507		}
508		var u User
509		if id, ok := s.usersByEmail[normEmail(inv.Email)]; ok {
510			u = s.users[id]
511		} else {
512			name = strings.TrimSpace(name)
513			if name == "" {
514				return User{}, Member{}, APIKey{}, invalid("a new user needs a name")
515			}
516			u = User{ID: s.newID("usr"), Email: inv.Email, Name: name, CreatedAt: now.UTC()}
517			s.users[u.ID] = u
518			s.usersByEmail[normEmail(u.Email)] = u.ID
519		}
520		m, err := s.addMember(inv.OrgID, u.ID, inv.Role, now)
521		if err != nil {
522			return User{}, Member{}, APIKey{}, err
523		}
524		k, err := s.createAPIKey(inv.OrgID, u.ID, "Default", now)
525		if err != nil {
526			return User{}, Member{}, APIKey{}, err
527		}
528		t := now.UTC()
529		inv.AcceptedAt = &t
530		s.invites[inv.ID] = inv
531		return u, m, k, nil
532	}
